    private void markFailed(ImportTask task) {
        task.setStatus("FAILED");
        task.setCompletedAt(LocalDateTime.now());
        importTaskMapper.update(task);
    }

    private int extractArchive(byte[] archiveBytes, Path uploadDir) throws IOException {
        int entryCount = 0;
        try (ZipInputStream zip = new ZipInputStream(new ByteArrayInputStream(archiveBytes))) {
            ZipEntry entry;
            while ((entry = zip.getNextEntry()) != null) {
                entryCount++;
                Path target = uploadDir.resolve(entry.getName()).normalize();
                if (!target.startsWith(uploadDir)) {
                    continue;
                }
                if (entry.isDirectory()) {
                    Files.createDirectories(target);
                } else {
                    Path parent = target.getParent();
                    if (parent != null) {
                        Files.createDirectories(parent);
                    }
                    Files.copy(zip, target, StandardCopyOption.REPLACE_EXISTING);
                }
            }
        }
        return entryCount;
    }

    private Path resolveDocumentRoot(Path uploadDir) throws IOException {
        try (var children = Files.list(uploadDir)) {
            Optional<Path> firstDirectory = children
                    .filter(Files::isDirectory)
                    .sorted()
                    .findFirst();
            return firstDirectory.orElse(uploadDir);
        }
    }
