    task.setCreatedAt(LocalDateTime.now());
    importTaskMapper.insert(task);

    Path uploadDir = Paths.get(tmpDir).resolve(UUID.randomUUID().toString());
    try {
        byte[] archiveBytes;
        try {
            archiveBytes = Base64.getDecoder().decode(zipContentBase64);
